old='function inventoryState(hero){try{if(typeof ROOT.loadState==="function")return ROOT.loadState(hero)}catch(e){}return null}\nfunction saveInventoryState(hero,st){if(!st)return false;try{if(typeof ROOT.key==="function"){localStorage.setItem(ROOT.key(hero),JSON.stringify(st));return true}}catch(e){}try{ROOT.saveState?.(hero,st);return true}catch(e){}return false}\nfunction addInventoryItem(hero,itemId,qty){const st=inventoryState(hero);if(!st)return false;st.inventory=Array.isArray(st.inventory)?st.inventory:[];for(let i=0;i<qty;i++){let entry={itemId};try{if(typeof ROOT.makeInventoryEntry==="function")entry=ROOT.makeInventoryEntry(itemId)}catch(e){}st.inventory.push(entry)}return saveInventoryState(hero,st)}\nfunction addGold(hero,amount){const st=inventoryState(hero);if(!st)return false;let current=Number(st.gold)||0;try{if(typeof ROOT.gensHeroGold==="function")current=Number(ROOT.gensHeroGold(hero))||0}catch(e){}st.gold=current+Math.max(0,Number(amount)||0);return saveInventoryState(hero,st)}\nfunction grantRewards(hero,gold,items){if(gold>0)addGold(hero,gold);for(const it of normalizeItems(items))addInventoryItem(hero,it.itemId,it.qty)}'
new='function heroStorageKey(hero){try{if(typeof ROOT.key==="function")return String(ROOT.key(hero))}catch(e){}return "z40k_"+String(hero||"")+"_v1"}\nfunction inventoryState(hero){try{if(typeof ROOT.loadState==="function"){const st=ROOT.loadState(hero);if(st&&typeof st==="object")return st}}catch(e){}const st=readJson(heroStorageKey(hero),null);return st&&typeof st==="object"?st:null}\nfunction saveInventoryState(hero,st){if(!st)return false;try{localStorage.setItem(heroStorageKey(hero),JSON.stringify(st));return true}catch(e){return false}}\nfunction rewardInventoryEntry(itemId){try{if(typeof ROOT.makeInventoryEntry==="function")return ROOT.makeInventoryEntry(itemId)}catch(e){}let it=null;try{it=(ROOT.dungeonItems?.()||[]).find(x=>String(x?.id||"")===String(itemId))||null}catch(e){}return {uid:"i_"+Date.now().toString(36)+"_"+Math.random().toString(36).slice(2,8),itemId:String(itemId),ammo:Math.max(0,Number(it?.ammoCapacity)||0),reloads:Math.max(0,Number(it?.reloads)||0)}}\nfunction addInventoryItem(hero,itemId,qty){const st=inventoryState(hero);if(!st)return false;st.inventory=Array.isArray(st.inventory)?st.inventory:[];for(let i=0;i<qty;i++)st.inventory.push(rewardInventoryEntry(itemId));return saveInventoryState(hero,st)}\nfunction addGold(hero,amount){const st=inventoryState(hero);if(!st)return false;let current=Number(st.gold)||0;try{if(typeof ROOT.gensHeroGold==="function")current=Number(ROOT.gensHeroGold(hero))||current}catch(e){}st.gold=current+Math.max(0,Number(amount)||0);return saveInventoryState(hero,st)}\nfunction grantRewards(hero,gold,items){const st=inventoryState(hero);if(!st)return false;st.inventory=Array.isArray(st.inventory)?st.inventory:[];let current=Number(st.gold)||0;try{if(typeof ROOT.gensHeroGold==="function")current=Number(ROOT.gensHeroGold(hero))||current}catch(e){}st.gold=current+Math.max(0,Number(gold)||0);for(const it of normalizeItems(items))for(let i=0;i<it.qty;i++)st.inventory.push(rewardInventoryEntry(it.itemId));const ok=saveInventoryState(hero,st);if(ok)try{ROOT.renderInventory?.();ROOT.renderHands?.();ROOT.renderGear?.()}catch(e){}return ok}'
