new='function openChest(chestId){const ctx=currentContext();if(!ctx||!ctx.hero)return false;const chest=ctx.content.chests.find(c=>c.id===String(chestId));if(!chest||ctx.state.openedChests[chest.id])return false;const itemCount=chest.items.reduce((n,i)=>n+i.qty,0);if(!grantRewards(ctx.hero,chest.gold,chest.items)){try{ROOT.DungeonCore01?.modal?.("⚠️ Coffre non ouvert","La récompense n’a pas pu être enregistrée dans l’inventaire. Le coffre reste disponible.")}catch(e){}return false}ctx.state.openedChests[chest.id]=true;markCellFloor(ctx.x,chest.cell);removeExactChestScene(chest.id);persistSpatial(ctx.x);writeRuntime(ctx.x);try{ROOT.showToast?.("🎁 Coffre ouvert · "+chest.gold+" or · "+itemCount+" objet(s)")}catch(e){}try{ROOT.DungeonCore01?.modal?.("🎁 Coffre ouvert",(chest.gold?chest.gold+" or":"")+(chest.gold&&itemCount?" · ":"")+(itemCount?itemCount+" objet(s) ajouté(s) à l’inventaire":""));ROOT.DungeonCore01?.render?.()}catch(e){}return true}'
